<template>
  <section class="role-section">
    <header><p class="eyebrow">Pharmacist</p><h2>Pharmacy stock and dispensing</h2><p>Monitor pharmacy-listed items and stock levels in this branch.</p></header>
    <div class="metric-grid"><article v-for="metric in metrics" :key="metric.label" class="metric"><span>{{ metric.label }}</span><strong>{{ metric.value }}</strong><small>{{ metric.note }}</small></article></div>
    <div class="panel-grid"><article class="panel"><h3>Pharmacy stock levels</h3><div class="bars"><div v-for="item in stockBars" :key="item.id"><span>{{ item.name }}</span><i><b :style="{ width: `${item.width}%` }" /></i><strong>{{ item.stock }}</strong></div></div></article><article class="panel"><h3>Items needing attention</h3><div v-if="attentionItems.length" class="table-wrap"><table><thead><tr><th>Medicine / item</th><th>Stock</th><th>Dispensing</th></tr></thead><tbody><tr v-for="item in attentionItems" :key="item.id"><td>{{ item.name || item.itemName || 'Item' }}</td><td>{{ item.currentStock ?? 0 }}</td><td>{{ dispensingLabel(item.dispensingClass) }}</td></tr></tbody></table></div><p v-else class="empty">No pharmacy stock alerts.</p></article></div>
  </section>
</template>
<script setup>
import { computed } from 'vue'
const props = defineProps({ items: { type: Array, default: () => [] } })
const pharmacyItems = computed(() => props.items.filter(item => item.pharmacyEnabled === true))
const needsRestock = item => Number(item.currentStock || 0) <= Number(item.reorderLevel || item.minimumStock || 0)
const metrics = computed(() => [{ label: 'Pharmacy-listed items', value: pharmacyItems.value.length, note: 'Available in this branch' }, { label: 'Low stock', value: pharmacyItems.value.filter(needsRestock).length, note: 'Review for replenishment' }, { label: 'Prescription required', value: pharmacyItems.value.filter(item => item.dispensingClass === 'prescription_required').length, note: 'Dispense with a prescription' }])
const stockBars = computed(() => [...pharmacyItems.value].sort((a, b) => Number(a.currentStock || 0) - Number(b.currentStock || 0)).slice(0, 6).map(item => ({ id: item.id, name: String(item.name || item.itemName || 'Item').slice(0, 18), stock: Number(item.currentStock || 0), width: Math.max(Number(item.currentStock || 0) ? 8 : 0, Math.min(100, Number(item.currentStock || 0) / Math.max(1, Number(item.reorderLevel || item.minimumStock || 1) * 3) * 100)) })))
const attentionItems = computed(() => pharmacyItems.value.filter(item => needsRestock(item) || item.dispensingClass === 'unclassified').slice(0, 8))
const dispensingLabel = value => ({ prescription_required: 'Prescription required', general_sale: 'General sale', restricted: 'Restricted', unclassified: 'Needs setup' })[value] || 'Not set'
</script>
<style scoped>
.role-section{display:grid;gap:1rem;color:#4a3324}.role-section header h2{margin:.25rem 0;font:600 1.65rem Georgia,serif;color:#402719}.role-section header p:last-child{margin:.3rem 0;color:#806b5a}.eyebrow{margin:0;color:#91643f;font-size:.68rem;font-weight:700;letter-spacing:.18em;text-transform:uppercase}.metric-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:.8rem}.metric,.panel{min-width:0;border:1px solid #ead8c2;border-radius:1rem;background:#fffdf9;padding:1rem;box-shadow:0 8px 24px #4b311e0a}.metric span,.metric small{display:block;color:#806b5a;font-size:.8rem}.metric strong{display:block;margin:.45rem 0;color:#4a2d1c;font-size:1.7rem}.panel-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr));gap:1rem}.panel h3{margin:0 0 .8rem;color:#4a2d1c;font-size:1rem}.bars{display:grid;gap:.75rem}.bars>div{display:grid;grid-template-columns:7rem minmax(2rem,1fr) 2rem;align-items:center;gap:.6rem;font-size:.76rem}.bars i{height:.55rem;overflow:hidden;border-radius:1rem;background:#f2e8dc}.bars b{display:block;height:100%;border-radius:inherit;background:#a97851}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:.82rem}th,td{padding:.65rem .5rem;border-bottom:1px solid #efe3d5;white-space:nowrap}th{color:#806b5a;font-size:.7rem;text-transform:uppercase;letter-spacing:.06em}.empty{color:#806b5a;font-size:.85rem}@media(max-width:600px){.role-section header h2{font-size:1.4rem}th,td{padding:.55rem .4rem;font-size:.75rem}}
</style>
